// Simple Gaussian blur. None of this is optimized for learning purposes.

// Quick way to toggle blur using the preprocessor. Just set to 0 to disable or anything else to enable.
#define BLURRED 1
// Define how large the kernel is. Don't set these to 0! Odd values work best.
#define KERNEL_WIDTH 11
#define KERNEL_HEIGHT 11

float gauss(float x, float y, float stDev)
{
    return (1.0 / 2.0 * 3.1415 * pow(stDev, 2.0)) * exp(-((pow(x, 2.0) + pow(y, 2.0)) / 2.0 * pow(stDev, 2.0)));
}

// Sample a standard 2D Gauss function at specific X & Y coords based on the kernel index requested
float sampleGaussFunction(int kernelIndex)
{
    float kernelWidth = float(KERNEL_WIDTH);
    float kernelHeight = float(KERNEL_HEIGHT);

    // Get x and y sample coordinates for Gauss function. Center is at (0,0), so do some offsets
    // since kernel indices start at 0
    float x = -floor(kernelWidth / 2.0) + float(kernelIndex % KERNEL_WIDTH);
    float y = -floor(kernelHeight / 2.0) + floor(float(kernelIndex) / kernelWidth);

    return gauss(x, y, 0.3);
}

vec4 processKernel(vec2 uv, float[KERNEL_WIDTH * KERNEL_HEIGHT] kernel)
{
    // Calculate step size to sample adjacent pixels
    float stepSize = 1.0;
    float stepX = stepSize / iResolution.x;
    float stepY = stepSize / iResolution.y;

    // Initialize result color for current pixel
    vec4 result = vec4(0);

    // Array definitions require ints, but the rest of the code uses floats, so cast once.
    float kernelWidth = float(KERNEL_WIDTH);
    float kernelHeight = float(KERNEL_HEIGHT);

    // Accumulate the final pixel color sample by sample
    for(float y = 0.0; y < kernelHeight; y++)
    {
        for(float x = 0.0; x < kernelWidth; x++)
        {
            // Calculate sample offset for both X and Y coordinates.
            vec2 sampleOffset = vec2(0);
            sampleOffset.x = stepX * (-floor(kernelWidth / 2.0) + x);
            sampleOffset.y = stepY * (floor(kernelHeight / 2.0) - y);
            vec4 currentSample = texture(iChannel0, uv + sampleOffset);

            // Traverse the kernel from bottom right to top left, flipping it.
            // Flipping the kernel is part of the convolution operation.
            int kernelIndex = int((kernelWidth * kernelHeight - 1.0) - (kernelWidth * y + x));
            result += kernel[kernelIndex] * currentSample;
        }
    }

    return result;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // Initialize the kernel by sampling a 2D Gauss function at specific locations
    // Calculate the sum of all kernel terms for normalization
    float[KERNEL_WIDTH * KERNEL_HEIGHT] kernel;
    float kernelSum = 0.0;
    for(int i = 0; i < KERNEL_WIDTH * KERNEL_HEIGHT; i++)
    {
        float gaussSample = sampleGaussFunction(i);
        kernel[i] = gaussSample;
        kernelSum += gaussSample;
    }

    // Normalize kernel values so the sum of all entries is 1
    for(int i = 0; i < KERNEL_WIDTH * KERNEL_HEIGHT; i++)
    {
        kernel[i] /= kernelSum;
    }

    // Output the desired result to screen
    #if BLURRED != 0
    fragColor = processKernel(uv, kernel);
    #else
    fragColor = texture(iChannel0, uv);
    #endif
}
